<script setup>
import {useRouter} from 'vue-router';import {api,clearSession} from '../../src/services/api.js';import {useCollection} from '../../src/services/useCollection.js';import {LegacyState,LegacyPager,date} from '../../src/services/legacy.js';import BusinessPage from '../../src/components/BusinessPage.vue';
const router=useRouter(),state=useCollection('/users/me/sessions',null,()=>({}));
async function revoke(item){await state.run(async()=>{await api('/users/me/sessions/'+item.id,{method:'DELETE'});if(item.current){clearSession();await router.replace('/login')}else await state.load(state.page)})}
async function all(){await state.run(async()=>{await api('/users/me/sessions',{method:'DELETE'});clearSession();await router.replace('/login')})}
</script><template><BusinessPage title="Phiên đăng nhập"><LegacyState :state="state"/><button :disabled="state.busy" @click="all">Thu hồi mọi phiên và đăng xuất</button><p v-if="!state.busy&&!state.items.length">Không có phiên để hiển thị.</p><section v-for="item in state.items" :key="item.id"><h2>{{item.current?'Phiên hiện tại':'Phiên khác'}}</h2><p>{{item.userAgent||'Thiết bị không xác định'}}</p><p>Tạo: {{date(item.createdAt)}} · Hết hạn: {{date(item.expiresAt)}} · {{item.revoked?'Đã thu hồi':'Đang hoạt động'}}</p><button v-if="!item.revoked" :disabled="state.busy" @click="revoke(item)">Thu hồi phiên</button></section><LegacyPager :state="state"/></BusinessPage></template>
